﻿using System;

namespace CSharp
{
    public class _584B
    {
        private static int m = 1000000007;

        public static void Main()
        {
            int n = int.Parse(Console.ReadLine());
            Console.WriteLine(((Power(27, n) - Power(7, n)) % m + m) % m);
        }

        private static long Power(long n, long k)
        {
            long result = 1;

            if (k > 0)
            {
                result *= Power(n, k / 2);
                result %= m;

                result *= result;
                result %= m;

                if (k % 2 == 1)
                {
                    result *= n;
                    result %= m;
                }
            }

            return result;
        }
    }
}
